package com.gathin.tvhome;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public class PlaylistPolicyTest {
    private final String a="p-00000000-0000-0000-0000-000000000001",b="p-00000000-0000-0000-0000-000000000002";
    private void rejects(Runnable r){try{r.run();fail("Invalid playlist accepted");}catch(IllegalArgumentException expected){}}
    @Test public void defaultsAreOffAndFifteenMinutes(){PlaylistPolicy.Spec s=PlaylistPolicy.parse("");assertFalse(s.enabled);assertEquals(900,s.seconds);assertTrue(s.tokens.isEmpty());}
    @Test public void choicesRoundTripAndKeepSpecifiedOrder(){PlaylistPolicy.Spec s=new PlaylistPolicy.Spec(true,900,true,Arrays.asList(b,a));PlaylistPolicy.Spec restored=PlaylistPolicy.parse(s.encode());assertEquals(s.tokens,restored.tokens);assertTrue(restored.shuffle);assertTrue(restored.enabled);assertEquals(900,restored.seconds);}
    @Test public void duplicatesPathsUnsupportedIntervalsAndTooFewEnabledEntriesAreRejected(){rejects(()->new PlaylistPolicy.Spec(true,900,false,Arrays.asList(a,a)));rejects(()->new PlaylistPolicy.Spec(true,900,false,Arrays.asList(a,"../video.mp4")));rejects(()->new PlaylistPolicy.Spec(true,9,false,Arrays.asList(a,b)));rejects(()->new PlaylistPolicy.Spec(true,900,false,Collections.singletonList(a)));rejects(()->PlaylistPolicy.parse("v1|on|900|remote|"+a+","+b));rejects(()->PlaylistPolicy.parse("v1|off|0900|sequential|"+a+"|extra"));}
    @Test public void membershipIsDefensiveAndBounded(){List<String> tokens=new ArrayList<>(Arrays.asList(a,b));PlaylistPolicy.Spec s=new PlaylistPolicy.Spec(true,900,false,tokens);tokens.clear();assertEquals(2,s.tokens.size());try{s.tokens.clear();fail();}catch(UnsupportedOperationException expected){}List<String> excessive=new ArrayList<>();for(int i=0;i<9;i++)excessive.add(String.format(Locale.ROOT,"p-%08x-0000-0000-0000-000000000000",i));rejects(()->new PlaylistPolicy.Spec(true,900,false,excessive));}
    @Test public void timeAwayFromHomeCannotConsumeTheWallpaperInterval(){PlaylistPolicy.Clock c=new PlaylistPolicy.Clock(900000,900000);c.start(100);c.stop(30100);assertEquals(870000,c.remaining(99999999));c.start(100000000);assertFalse(c.due(100869999));assertTrue(c.due(100870000));}
    @Test public void deadlineAndPauseAreExactAndPersistedRemainingIsClamped(){PlaylistPolicy.Clock c=new PlaylistPolicy.Clock(60000,999999);assertEquals(60000,c.remaining(0));c.start(0);assertFalse(c.due(59999));assertTrue(c.due(60000));c.stop(60000);assertFalse(c.due(100000));c.reset(100000);c.start(100000);assertEquals(60000,c.remaining(99999));assertTrue(c.due(160000));c.restore(12000);assertFalse(c.due(999999));c.start(200000);assertTrue(c.due(212000));c.restore(-1);assertEquals(0,c.remaining(0));}
    @Test public void sequentialWrapsAndShuffleDoesNotImmediatelyRepeat(){Random r=new Random(7);assertEquals(0,PlaylistPolicy.next(3,2,false,r));for(int i=0;i<3;i++)for(int n=0;n<100;n++){int next=PlaylistPolicy.next(3,i,true,r);assertNotEquals(i,next);assertTrue(next>=0&&next<3);}assertEquals(0,PlaylistPolicy.next(1,0,true,r));}
    @Test public void playlistChoicesBelongToProfilesAndRecoveryButPlaybackDoesNot(){assertTrue(SetupValues.KEYS.contains(WallpaperPlaylistChoice.KEY));assertTrue(LocalProfiles.SCOPED.contains(WallpaperPlaylistChoice.KEY));assertFalse(SetupValues.KEYS.contains(WallpaperPlaylist.PLAYBACK));assertNotEquals(LocalProfiles.filename("one",WallpaperPlaylist.PLAYBACK),LocalProfiles.filename("two",WallpaperPlaylist.PLAYBACK));}
}
